import{_ as t,o as n,c as e,a3 as s}from"./chunks/framework.DxEvSMU4.js";const b=JSON.parse('{"title":"P2 程式撰寫助理","description":"","frontmatter":{},"headers":[],"relativePath":"examples/p2-coding.md","filePath":"examples/p2-coding.md","lastUpdated":1793028953000}'),d={name:"examples/p2-coding.md"};function l(o,a,p,i,r,c){return n(),e("div",null,[...a[0]||(a[0]=[s(`<h1 id="p2-程式撰寫助理" tabindex="-1">P2 程式撰寫助理 <a class="header-anchor" href="#p2-程式撰寫助理" aria-label="Permalink to &quot;P2 程式撰寫助理&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">本章屬性</p><ul><li>等級: ○ 依情境</li><li>狀態: 可閱讀 (部分資料待核對)</li><li>資料基準日: 2026-10-26</li><li>待查證: 編輯器整合步驟依 Ollama 與 VS Code 官方文件整理, 未實機驗證; VS Code 使用本機模型時是否仍有資料送往外部服務, 官方文件未說明; 64K 上下文在各硬體等級的記憶體需求未實測; 文中的類比為整理者所寫, 不代表技術上完全等同</li></ul></div><p><strong>結論</strong>: 只做「解釋, 撰寫, 檢查程式碼」時, 里程碑 1 (M0 至 M2) 就夠: 在 Open WebUI 貼上程式碼即可, 程式碼不離開本機. 想在編輯器裡使用時, 可以用 Ollama 官方的 VS Code 擴充套件或終端機的程式代理, 但這類工具建議上下文至少 64K, 對顯示記憶體的要求明顯較高. 只要讓模型執行程式碼, 就必須加上 M7 的沙箱, 不能直接在自己的電腦上執行.</p><p><strong>對象</strong>: 個人. <strong>需要的模組</strong>: M1, M2 (需要執行程式時加 M7).</p><div class="tip custom-block"><p class="custom-block-title">本頁常見名詞</p><table tabindex="0"><thead><tr><th>詞</th><th>意思</th></tr></thead><tbody><tr><td>上下文長度 (context length)</td><td>模型一次能處理的文字量上限, 包含貼進去的程式碼與模型的回答; 64K 指 6 萬多個 token</td></tr><tr><td>擴充套件 (extension)</td><td>安裝在 VS Code 上, 為編輯器加功能的外掛程式</td></tr><tr><td>程式代理 (coding agent)</td><td>不只回答問題, 還能自己讀寫檔案, 執行指令的程式</td></tr><tr><td>沙箱 (sandbox)</td><td>與自己的電腦隔開的執行環境, 裡面發生的事不影響外面</td></tr><tr><td>OpenAI 相容 API</td><td>許多工具共用的一種請求格式; 推論伺服器支援這種格式, 工具就能直接接上</td></tr><tr><td>git diff</td><td>列出檔案修改前後差異的指令, 用來逐行檢查改了什麼</td></tr><tr><td>KV cache</td><td>模型處理長內容時暫存在記憶體中的中間結果, 上下文越長占用越多 (見 <a href="/lanai-handbook/know/k2-quantization">K2</a>)</td></tr></tbody></table><p>完整詞彙見<a href="/lanai-handbook/ref/glossary">術語對照</a>.</p></div><h2 id="情境" tabindex="-1">情境 <a class="header-anchor" href="#情境" aria-label="Permalink to &quot;情境&quot;">​</a></h2><p>讀者是會寫一些程式的人: 開發者, 學生, 或需要寫 PowerShell, Python, Bash 腳本的 IT 與資安人員. 原本遇到問題時會查官方文件, 搜尋論壇, 或使用雲端的程式助理. 痛點在於公司的程式碼, 設定檔與日誌片段常含有內部主機名稱, 帳號或金鑰, 不一定適合貼到外部服務.</p><p>本範例分成三種用法, 由簡單到進階:</p><table tabindex="0"><thead><tr><th>用法</th><th>做什麼</th><th>需要的模組</th><th>適合</th></tr></thead><tbody><tr><td>A. 在對話介面貼上程式碼</td><td>請模型解釋, 撰寫或檢查一段程式碼, 讀者自己複製回編輯器</td><td>M1, M2</td><td>所有讀者, 沒有工程背景也能用</td></tr><tr><td>B. 編輯器內的對話</td><td>在 VS Code 的對話面板選用本機模型, 直接參照開啟中的檔案</td><td>M1 (加編輯器擴充套件)</td><td>每天寫程式的讀者</td></tr><tr><td>C. 程式代理</td><td>模型可以讀寫專案檔案, 並執行指令</td><td>M1, 加 M7 的沙箱</td><td>熟悉容器與權限設定的讀者</td></tr></tbody></table><p>用法 A 就像請一位同事看自己貼過去的程式碼, 對方看不到其他檔案, 也不會動手改. 用法 C 則是把鍵盤交給對方, 所以要先準備一個隔離的工作環境.</p><h2 id="需要的模組" tabindex="-1">需要的模組 <a class="header-anchor" href="#需要的模組" aria-label="Permalink to &quot;需要的模組&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模組</th><th>里程碑</th><th>在本範例的用途</th></tr></thead><tbody><tr><td><a href="/lanai-handbook/build/m0-foundation">M0 基礎環境</a></td><td>里程碑 1</td><td>單機加 Docker 即可</td></tr><tr><td><a href="/lanai-handbook/build/m1-inference">M1 推論伺服器</a></td><td>里程碑 1</td><td>以 Ollama 執行程式專用或通用模型, 只綁 127.0.0.1:11434</td></tr><tr><td><a href="/lanai-handbook/build/m2-ui-proxy">M2 使用者介面與反向代理</a></td><td>里程碑 1</td><td>用法 A 的對話介面</td></tr><tr><td><a href="/lanai-handbook/build/m7-tools-sandbox">M7 工具與沙箱</a> (M7.3 節)</td><td>里程碑 3 的模組</td><td>只有用法 C, 或要讓模型執行程式碼時才需要</td></tr></tbody></table><h2 id="流程" tabindex="-1">流程 <a class="header-anchor" href="#流程" aria-label="Permalink to &quot;流程&quot;">​</a></h2><p>三種用法的差別在於模型能碰到什麼. 用法 A 只看得到讀者貼上的文字; 用法 B 看得到編輯器中開啟的檔案, 但改不改由讀者決定; 用法 C 能自己改檔案, 執行指令, 所以放在隔離的沙箱裡, 改完由讀者檢查差異後才合併. 下圖依序畫出三種用法的資料走向.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>用法 A: 對話介面</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[讀者] --貼上程式碼--&gt; [瀏覽器 http://127.0.0.1:3000]</span></span>
<span class="line"><span>   |</span></span>
<span class="line"><span>   v</span></span>
<span class="line"><span>[Open WebUI] --&gt; [Ollama 127.0.0.1:11434 對話模型]</span></span>
<span class="line"><span>   |</span></span>
<span class="line"><span>   | 說明或修改建議</span></span>
<span class="line"><span>   v</span></span>
<span class="line"><span>[讀者] --&gt; 自己檢查後, 手動貼回編輯器</span></span>
<span class="line"><span></span></span>
<span class="line"><span>用法 B: 編輯器內的對話</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[VS Code 對話面板]</span></span>
<span class="line"><span>   |</span></span>
<span class="line"><span>   | Ollama 擴充套件, 預設連 http://127.0.0.1:11434</span></span>
<span class="line"><span>   v</span></span>
<span class="line"><span>[Ollama 對話模型]</span></span>
<span class="line"><span>   |</span></span>
<span class="line"><span>   | 回答與程式碼建議</span></span>
<span class="line"><span>   v</span></span>
<span class="line"><span>[讀者] --&gt; 決定是否套用到檔案</span></span>
<span class="line"><span></span></span>
<span class="line"><span>用法 C: 程式代理 (需要 M7)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[讀者交辦任務] --&gt; [程式代理] --OpenAI 相容 API--&gt; [Ollama]</span></span>
<span class="line"><span>   |</span></span>
<span class="line"><span>   | 程式代理執行指令, 修改檔案</span></span>
<span class="line"><span>   v</span></span>
<span class="line"><span>[沙箱容器: Docker + gVisor, 無網路, 只掛載專案副本]</span></span>
<span class="line"><span>   |</span></span>
<span class="line"><span>   v</span></span>
<span class="line"><span>[讀者檢查差異 (git diff)] --&gt; 確認後才合併回正式專案</span></span></code></pre></div><h2 id="設定要點" tabindex="-1">設定要點 <a class="header-anchor" href="#設定要點" aria-label="Permalink to &quot;設定要點&quot;">​</a></h2><p>以下依官方文件整理, 未實機驗證.</p><p><strong>用法 A: Open WebUI</strong></p><ul><li>介面設定沿用 M2. 建立一個專用模型 (Workspace &gt; Models), 在系統提示寫下固定要求. 系統提示是每次對話開始前自動交給模型的說明, 讀者不必每次重打. 例如:</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>讀者會貼上程式碼或錯誤訊息. 請用繁體中文回答, 依下列順序:</span></span>
<span class="line"><span>1. 用兩三句話說明這段程式碼在做什麼.</span></span>
<span class="line"><span>2. 列出可能的錯誤或風險 (含安全問題, 例如寫死的密碼, 未檢查的輸入).</span></span>
<span class="line"><span>3. 提出修改後的程式碼, 並說明改了哪裡.</span></span>
<span class="line"><span>不確定的地方直接說不確定, 不要編造不存在的函式或參數.</span></span></code></pre></div><ul><li>Open WebUI 的程式碼執行與程式碼直譯器預設都啟用 (<code>ENABLE_CODE_EXECUTION</code>, <code>ENABLE_CODE_INTERPRETER</code> 預設為 True), 預設引擎為在瀏覽器內執行的 Pyodide; 官方文件已把 Pyodide 與伺服器端的 Jupyter 引擎標為舊版. 若不需要在介面中執行程式碼, 可以把這兩個設定關閉 (屬 <code>ConfigVar</code>, 第一次啟動後改在管理介面調整); 需要時改依 M7 的做法.</li></ul><p><strong>用法 B: VS Code 加 Ollama 擴充套件</strong></p><ul><li>Ollama 官方文件的步驟: 從 VS Code Marketplace 安裝 Ollama 擴充套件, 開啟 Chat, 在輸入框下方的模型選單選 <strong>Ollama</strong> 區段的模型. 擴充套件預設從 <code>http://127.0.0.1:11434</code> 讀取模型清單; 本機模型不需要登入.</li><li>官方文件要求 VS Code 1.127 以上, 並建議把 Ollama 的上下文長度設為至少 64K, 設定後重新載入 VS Code 視窗.</li><li>VS Code 官方部落格說明, 自備模型 (BYOK) 可以在不登入 GitHub, 沒有 Copilot 方案的情況下使用; 但語意搜尋, 行內建議與依賴嵌入的功能仍需要 GitHub 帳號或 Copilot. 換句話說, 這條路線提供的是對話功能, 不是自動補全.</li><li>VS Code 的遙測以 <code>telemetry.telemetryLevel</code> 設定, 可設為 <code>off</code>; 官方文件說明這個設定不管擴充套件, 每個擴充套件的遙測要各自查文件.</li><li>其他編輯器擴充套件也能接 Ollama. 選用前先確認維護狀態: 例如 Continue 的 GitHub 儲存庫已標示「不再積極維護, 唯讀」, 不適合新導入.</li></ul><p><strong>用法 C: 程式代理</strong></p><ul><li>Ollama 官方文件列出 OpenCode 等終端機程式代理的整合方式, 例如以 <code>ollama launch opencode</code> 啟動; 官方同樣註明 OpenCode 需要 64K 以上的上下文.</li><li>程式代理會執行指令與修改檔案, 因此依 M7.3 節放進沙箱. 沙箱可以想成一間只放專案影本的工作室: 代理在裡面怎麼改都不會碰到原件. 具體做法是 Docker 加 gVisor (Google 開源的容器隔離層) (<code>--runtime runsc</code>), <code>--network none</code>, <code>--read-only</code>, 非 root 使用者, <code>--cap-drop ALL</code>, 記憶體, CPU 與行程數上限, 每次用新容器. 只掛載專案的副本, 不掛載家目錄, SSH 金鑰或雲端憑證所在的資料夾.</li><li>64K 上下文的 KV cache 會占用大量記憶體 (見 K2.3 節). 硬體等級 A 至 C 的讀者, 用法 A 通常比較實際 (推論, 信心: 中高).</li></ul><h2 id="驗收方式" tabindex="-1">驗收方式 <a class="header-anchor" href="#驗收方式" aria-label="Permalink to &quot;驗收方式&quot;">​</a></h2><p>用自己常寫的語言準備 20 題測試, 存進 M6.1 節的測試集:</p><table tabindex="0"><thead><tr><th>類型</th><th>題數</th><th>範例</th><th>通過標準</th></tr></thead><tbody><tr><td>解釋</td><td>5</td><td>貼一段既有的腳本, 請模型說明用途</td><td>說明與實際行為一致</td></tr><tr><td>撰寫</td><td>5</td><td>「寫一個 Python 函式, 讀取 CSV 並依第二欄加總」</td><td>讀者在沙箱或自己的測試環境執行, 結果正確</td></tr><tr><td>找錯</td><td>5</td><td>貼一段刻意放入錯誤的程式碼 (例如迴圈邊界錯一格)</td><td>指出正確的錯誤位置</td></tr><tr><td>安全檢查</td><td>3</td><td>貼一段含寫死密碼與 SQL 字串拼接的程式碼</td><td>兩個問題都有指出</td></tr><tr><td>不知道就說不知道</td><td>2</td><td>詢問一個虛構套件的用法</td><td>表示不確定, 不編造 API</td></tr></tbody></table><p>另外檢查兩件事: 以 <code>ss -tlnp</code> (Linux) 或 <code>lsof -i -P</code> (macOS) 確認 Ollama 只聽 127.0.0.1; 用法 C 則依 M7.5 節的要點, 確認沙箱內無法連線外部網路, 也無法寫入唯讀目錄.</p><h2 id="風險與限制" tabindex="-1">風險與限制 <a class="header-anchor" href="#風險與限制" aria-label="Permalink to &quot;風險與限制&quot;">​</a></h2><table tabindex="0"><thead><tr><th>風險</th><th>影響</th><th>因應方式</th></tr></thead><tbody><tr><td>模型產生看似正確但有錯的程式碼</td><td>錯誤進入正式環境, 或引入安全漏洞</td><td>一律經過讀者檢查與測試才合併; 重要程式碼搭配既有的程式碼審查流程</td></tr><tr><td>模型編造不存在的套件名稱</td><td>讀者照著安裝時, 可能裝到同名的惡意套件</td><td>安裝前到官方套件庫確認名稱, 發行者與下載量</td></tr><tr><td>程式碼中的機密</td><td>貼進介面的金鑰會留在對話紀錄與備份中</td><td>貼上前先把金鑰與密碼換成佔位符; 定期清理對話紀錄</td></tr><tr><td>程式代理執行具破壞力的指令</td><td>刪除檔案或修改系統設定</td><td>只在沙箱內執行, 只掛載專案副本; 合併前檢查 git diff</td></tr><tr><td>專案內的惡意設定檔</td><td>開啟來路不明的專案時, 編輯器或代理可能自動載入其中的 MCP 設定 (見 M7.1 節)</td><td>關閉編輯器的自動信任; 只開啟可信來源的專案</td></tr><tr><td>擴充套件的遙測或雲端功能</td><td>部分功能可能連到外部服務</td><td>關閉遙測; 只使用本機模型; 不確定時以防火牆觀察連線</td></tr></tbody></table><p>需要人工確認的步驟: 模型寫的程式碼在合併前由讀者檢查; 程式代理對檔案的修改在合併前逐一確認.</p><h2 id="參考來源" tabindex="-1">參考來源 <a class="header-anchor" href="#參考來源" aria-label="Permalink to &quot;參考來源&quot;">​</a></h2><ul><li><a href="https://docs.ollama.com/integrations" target="_blank" rel="noreferrer">Ollama 文件: Integrations</a></li><li><a href="https://docs.ollama.com/integrations/vscode" target="_blank" rel="noreferrer">Ollama 文件: VS Code</a></li><li><a href="https://docs.ollama.com/integrations/opencode" target="_blank" rel="noreferrer">Ollama 文件: OpenCode</a></li><li><a href="https://code.visualstudio.com/blogs/2026/06/18/byok-vscode" target="_blank" rel="noreferrer">VS Code 部落格: Use your own language model key in VS Code (2026-06-18)</a></li><li><a href="https://code.visualstudio.com/docs/configure/telemetry" target="_blank" rel="noreferrer">VS Code 文件: Telemetry</a></li><li><a href="https://github.com/continuedev/continue" target="_blank" rel="noreferrer">Continue GitHub 儲存庫 (維護狀態說明)</a></li><li><a href="https://docs.openwebui.com/reference/env-configuration" target="_blank" rel="noreferrer">Open WebUI 文件: Environment Variable Configuration (CODE_EXECUTION_ENGINE)</a></li><li>站內: <a href="/lanai-handbook/build/m7-tools-sandbox">M7 工具與沙箱</a>, <a href="/lanai-handbook/know/k2-quantization">K2 量化與記憶體需求估算</a></li><li>文中的類比 (請同事看程式碼, 把鍵盤交給對方, 只放影本的工作室): 整理者所寫, 無外部來源, 不應當作技術定義引用.</li></ul>`,34)])])}const u=t(d,[["render",l]]);export{b as __pageData,u as default};
